/** Linear scale √5: the playable grid has five times the cells of the source mask. */
export const COLS = OLD_COLS + 80;
export const ROWS = OLD_ROWS + FINE_ROW0;
export const CELL = 50;
export const GRID_GEN = 7;
export const WORLD_W = COLS * CELL;
export const WORLD_H = ROWS * CELL;
export const SOURCE_COLS = SRC_COLS;
export const SOURCE_ROWS = SRC_ROWS;
export { SOURCE_LAND };

export function sourceCell(c: number, r: number) {
  return {
    c: Math.min(SRC_COLS - 1, Math.max(0, Math.floor((c * SRC_COLS) / OLD_COLS))),
    r: Math.min(SRC_ROWS - 1, Math.max(0, Math.floor(((r - FINE_ROW0) * SRC_ROWS) / OLD_ROWS))),
  };
}

const blocks = new Map<string, { c: number; r: number }[]>();
export const LAND: number[][] = Array.from({ length: ROWS }, () => Array<number>(COLS).fill(0));
for (let r = 0; r < ROWS; r += 1) {
  for (let c = 0; c < COLS; c += 1) {
    const source = sourceCell(c, r);
    const bit = FINE_ROWS_TEXT[r]?.[c] === "1" ? 1 : 0;
    LAND[r]![c] = bit;
    // Only the original box maps onto the coarse source mask.
    if (!bit || r < FINE_ROW0 || c >= OLD_COLS) continue;
    const key = `${source.c},${source.r}`;
    const list = blocks.get(key);
    if (list) list.push({ c, r });
    else blocks.set(key, [{ c, r }]);
  }
}

/**
 * Islands: land not connected to the mainland (Bubiyan, Failaka, Warba and the small
 * islets). Each starts cut off: a bridge (roads laid over the sea) must link it to the
 * mainland, or to an island already linked, before anything there can be built.
 */
export type Island = { id: number; name: string; cells: number; c: number; r: number };
const islandOf = new Int32Array(COLS * ROWS).fill(-1);
export const ISLANDS: Island[] = [];
{
  const NAMED: { name: string; lon: number; lat: number }[] = [
    { name: "جزيرة بوبيان", lon: 48.2, lat: 29.8 },
    { name: "جزيرة فيلكا", lon: 48.36, lat: 29.44 },
    { name: "جزيرة وربة", lon: 48.06, lat: 29.98 },
  ];
  const comp = new Int32Array(COLS * ROWS).fill(-1);
  const groups: number[][] = [];
  for (let start = 0; start < COLS * ROWS; start += 1) {
    if (comp[start]! >= 0 || LAND[Math.floor(start / COLS)]![start % COLS] !== 1) continue;
    const id = groups.length;
    const cells: number[] = [];
    const stack = [start];
    comp[start] = id;
    while (stack.length) {
      const at = stack.pop()!;
      cells.push(at);
      const c = at % COLS,
        r = Math.floor(at / COLS);
      for (const [dc, dr] of [
        [1, 0],
        [-1, 0],
        [0, 1],
        [0, -1],
      ] as const) {
        const nc = c + dc,
          nr = r + dr;
        if (nc < 0 || nr < 0 || nc >= COLS || nr >= ROWS) continue;
        const k = nr * COLS + nc;
        if (comp[k]! >= 0 || LAND[nr]![nc] !== 1) continue;
        comp[k] = id;
        stack.push(k);
      }
    }
    groups.push(cells);
  }
  // The mainland is the piece holding the south-west corner.
  const mainland = comp[(ROWS - 1) * COLS]!;
  for (const [g, cells] of groups.entries()) {
    if (g === mainland) continue;
    let sc = 0,
      sr = 0,
      top = false;
    for (const k of cells) {
      sc += k % COLS;
      sr += Math.floor(k / COLS);
      if (k < COLS) top = true;
    }
    const c = sc / cells.length,
      r = sr / cells.length;
    // Iraqi coast at the north-east corner of the box is not part of the game.
    if (top && c > 230) {
      for (const k of cells) LAND[Math.floor(k / COLS)]![k % COLS] = 0;
      continue;
    }
    const lon = MAP_BOUNDS.west + ((c + 0.5) / COLS) * (MAP_BOUNDS.east - MAP_BOUNDS.west);
    const lat = MAP_BOUNDS.north - ((r + 0.5) / ROWS) * (MAP_BOUNDS.north - MAP_BOUNDS.south);
    const named = NAMED.find((n) => Math.hypot(n.lon - lon, n.lat - lat) < 0.08 && cells.length > 30);
    const id = ISLANDS.length;
    ISLANDS.push({ id, name: named?.name ?? "جزيرة صغيرة", cells: cells.length, c, r });
    for (const k of cells) islandOf[k] = id;
  }
}

/** The island a land cell belongs to, or -1 for the mainland and the sea. */
export function islandAt(c: number, r: number) {
  if (c < 0 || r < 0 || c >= COLS || r >= ROWS) return -1;
  return islandOf[r * COLS + c]!;
}

export function isIsland(c: number, r: number) {
  return islandAt(c, r) >= 0;
}

/** Scaled land cells that came from one source mask cell. */
export function cellsFromSource(c: number, r: number) {
  return blocks.get(`${c},${r}`) ?? [];
}
